// PaymentServiceServer is the server API for PaymentService service.
// All implementations must embed UnimplementedPaymentServiceServer
// for forward compatibility.
//
// 支付服务。
type PaymentServiceServer interface {
	// 查询当前 App 与客户端平台可购买的固定期限订阅 Offer。
	ListSubscriptionOffers(context.Context, *ListSubscriptionOffersRequest) (*ListSubscriptionOffersResponse, error)
	// 以 Payment 权威 Plan Revision 创建或恢复固定期限订阅 Provider Checkout。
	StartFixedTermSubscriptionCheckout(context.Context, *StartFixedTermSubscriptionCheckoutRequest) (*PurchaseView, error)
	// 以 Wallet 权威 Recharge Order 创建或恢复首笔 Provider Checkout。
	StartRechargeCheckout(context.Context, *StartRechargeCheckoutRequest) (*PurchaseView, error)
	// 经 Payment 跨类型身份校验后创建或恢复 Wallet 冻结的 Store Recharge 商品动作。
	PrepareStoreRechargePurchase(context.Context, *PrepareStoreRechargePurchaseRequest) (*StoreRechargePurchaseAction, error)
	// 验证 Store 凭证并创建或恢复一次性 Recharge Payment 与履约事实。
	VerifyStoreRechargePurchase(context.Context, *VerifyStoreRechargePurchaseRequest) (*PurchaseView, error)
	// 确认客户端已完成 StoreKit Transaction.finish；仅适用于要求客户端完成的 Store 交易。
	ConfirmStoreRechargePurchaseCompletion(context.Context, *ConfirmStoreRechargePurchaseCompletionRequest) (*PurchaseView, error)
	// 创建或恢复 iOS 自动续订订阅的冻结 StoreKit 商品动作。
	PrepareAppleSubscriptionPurchase(context.Context, *PrepareAppleSubscriptionPurchaseRequest) (*AppleSubscriptionPurchaseAction, error)
	// 验证 iOS 自动续订签名交易并应用 Provider Subscription 生命周期。
	VerifyAppleSubscriptionPurchase(context.Context, *VerifyAppleSubscriptionPurchaseRequest) (*PurchaseView, error)
	// 返回当前 User 的 Apple Store 订阅管理入口，不执行后台取消。
	GetAppleSubscriptionManagementAction(context.Context, *GetAppleSubscriptionManagementActionRequest) (*AppleSubscriptionManagementAction, error)
	// 创建或恢复 Google Play 自动续订订阅的冻结 Billing 商品动作。
	PrepareGoogleSubscriptionPurchase(context.Context, *PrepareGoogleSubscriptionPurchaseRequest) (*GoogleSubscriptionPurchaseAction, error)
	// 验证 Google Play 自动续订 Purchase Token 并应用 Provider Subscription 生命周期。
	VerifyGoogleSubscriptionPurchase(context.Context, *VerifyGoogleSubscriptionPurchaseRequest) (*PurchaseView, error)
	// 返回当前 User 的 Google Play 订阅管理入口，不执行后台取消。
	GetGoogleSubscriptionManagementAction(context.Context, *GetGoogleSubscriptionManagementActionRequest) (*GoogleSubscriptionManagementAction, error)
	// 重新验证既有 Apple 或 Google Store 购买，并按交易所有权修复本地投影。
	RestoreStorePurchases(context.Context, *RestoreStorePurchasesRequest) (*RestoreStorePurchasesResponse, error)
	// 返回当前 User 与永久合并别名拥有的一笔安全购买视图。
	GetMyPurchase(context.Context, *GetMyPurchaseRequest) (*PurchaseView, error)
	// 返回当前 User 与永久合并别名拥有的安全购买历史。
	ListMyPurchases(context.Context, *ListMyPurchasesRequest) (*ListMyPurchasesResponse, error)
	// 返回当前 User 的订阅权益及安全的 Store 管理动作，不从购买历史推断。
	GetMySubscription(context.Context, *GetMySubscriptionRequest) (*GetMySubscriptionResponse, error)
	// 在公开 Attempt 栅栏仍为当前值时创建或恢复下一笔串行 Payment Attempt。
	RetryMyPurchase(context.Context, *RetryMyPurchaseRequest) (*PurchaseView, error)
	// 查询当前已认证 User 在当前 App 与购买上下文下可见的公开 Payment Option。
	ListPurchaseOptions(context.Context, *ListPurchaseOptionsRequest) (*ListPurchaseOptionsResponse, error)
	// 创建支付单。
	CreatePayment(context.Context, *CreatePaymentRequest) (*Payment, error)
	// 查询支付单。
	GetPayment(context.Context, *GetPaymentRequest) (*Payment, error)
	// 关闭支付单。
	ClosePayment(context.Context, *ClosePaymentRequest) (*Payment, error)
	// 只读查询 Provider 权威状态并经状态机推进 Payment。
	RefreshPaymentProviderState(context.Context, *RefreshPaymentProviderStateRequest) (*RefreshPaymentProviderStateResponse, error)
	// 模拟支付成功。
	SimulatePaymentSuccess(context.Context, *SimulatePaymentSuccessRequest) (*Payment, error)
	// 查询支付列表。
	ListPayments(context.Context, *ListPaymentsRequest) (*ListPaymentResponse, error)
	// 查询 Payment 自有详情投影。
	GetPaymentDetail(context.Context, *GetPaymentDetailRequest) (*PaymentDetail, error)
	// 查询用户支付摘要，供 User Administration 临时聚合。
	GetUserPaymentSummary(context.Context, *GetUserPaymentSummaryRequest) (*UserPaymentSummary, error)
	// 查询当前 App 的 Payment 运营总览。
	GetPaymentOperationsSummary(context.Context, *GetPaymentOperationsSummaryRequest) (*PaymentOperationsSummary, error)
	// 查询跨工作流待办投影。
	ListPaymentWorkQueue(context.Context, *ListPaymentWorkQueueRequest) (*ListPaymentWorkQueueResponse, error)
	// 条件领取待办项。
	ClaimPaymentWorkQueueItem(context.Context, *MutatePaymentWorkQueueItemRequest) (*PaymentWorkQueueItem, error)
	// 条件转派待办项。
	ReassignPaymentWorkQueueItem(context.Context, *MutatePaymentWorkQueueItemRequest) (*PaymentWorkQueueItem, error)
	// 在来源事实收敛后完成待办协调记录。
	CompletePaymentWorkQueueItem(context.Context, *MutatePaymentWorkQueueItemRequest) (*PaymentWorkQueueItem, error)
	// 创建不可变 Payment Risk Policy 草稿版本。
	CreatePaymentRiskPolicyRevision(context.Context, *CreatePaymentRiskPolicyRevisionRequest) (*PaymentRiskPolicyRevision, error)
	// 发布指定 Payment Risk Policy 版本并退役上一版本。
	PublishPaymentRiskPolicyRevision(context.Context, *PublishPaymentRiskPolicyRevisionRequest) (*PaymentRiskPolicyRevision, error)
	// 查询 Payment Risk Policy 历史版本。
	ListPaymentRiskPolicyRevisions(context.Context, *ListPaymentRiskPolicyRevisionsRequest) (*ListPaymentRiskPolicyRevisionsResponse, error)
	// 查询 Payment 创建时冻结的风险决策。
	GetPaymentRiskDecision(context.Context, *GetPaymentRiskDecisionRequest) (*PaymentRiskDecision, error)
	// 查询待复核及历史 Payment Risk Review。
	ListPaymentRiskReviews(context.Context, *ListPaymentRiskReviewsRequest) (*ListPaymentRiskReviewsResponse, error)
	// 幂等批准或拒绝 Payment Risk Review。
	DecidePaymentRiskReview(context.Context, *DecidePaymentRiskReviewRequest) (*PaymentRiskDecision, error)
	// 查询 Payment 自有、严格按币种隔离的支付分析。
	GetPaymentAnalytics(context.Context, *GetPaymentAnalyticsRequest) (*GetPaymentAnalyticsResponse, error)
	// 查询支付事件列表。
	ListPaymentEvents(context.Context, *v1.PagingRequest) (*ListPaymentEventResponse, error)
	// 查询支付回调列表。
	ListPaymentCallbacks(context.Context, *v1.PagingRequest) (*ListPaymentCallbackResponse, error)
	// 使用原始回调和自动候选 Revision 重新验签及幂等处理。
	ReprocessPaymentCallback(context.Context, *ReprocessPaymentCallbackRequest) (*ReprocessPaymentCallbackResponse, error)
	// 处理渠道回调。
	HandleProviderCallback(context.Context, *HandleProviderCallbackRequest) (*HandleProviderCallbackResponse, error)
	mustEmbedUnimplementedPaymentServiceServer()
}

